#include <Cellerator/compiler/lto/implement_incremental_and_thin_summary_lto_v1.hh>
#include <algorithm>
namespace cellerator::compiler::lto::v1 {namespace{bool eq(artifact_identity_v1 a,artifact_identity_v1 b){return a.high==b.high&&a.low==b.low;}bool key(const thin_lto_identity_v1&a,const thin_lto_identity_v1&b){return eq(a.semantic,b.semantic)&&eq(a.profile,b.profile)&&eq(a.toolchain,b.toolchain)&&eq(a.passes,b.passes);}bool has(const std::vector<artifact_identity_v1>&v,artifact_identity_v1 x){return std::any_of(v.begin(),v.end(),[&](auto y){return eq(x,y);});}}
incremental_lto_plan_v1 plan_incremental_thin_lto_v1(const std::vector<thin_lto_object_v1>&now,const std::vector<thin_lto_object_v1>&cache)noexcept{incremental_lto_plan_v1 r;for(const auto&n:now){auto c=std::find_if(cache.begin(),cache.end(),[&](const auto&x){return eq(n.field,x.field)&&key(n.identity,x.identity);});if(c==cache.end())r.replan_fields.push_back(n.field);else{r.reused_summaries.push_back(n.field);if(c->full_ceir_cached)r.reused_full_ceir.push_back(n.field);}}bool changed=true;while(changed){changed=false;for(const auto&n:now)if(!has(r.replan_fields,n.field)&&std::any_of(n.calls.begin(),n.calls.end(),[&](auto c){return has(r.replan_fields,c);})){r.replan_fields.push_back(n.field);changed=true;}}return r;}
}
